      "output": "```js\nlet C=null,M=null,NB=null,E=null,mus=null,armed=false,muted=false;\nfor(const t of['pointerup','keydown'])addEventListener(t,()=>{armed=true;C&&C.resume();},true);\nfunction ac(){if(armed&&!C){C=new AudioContext();M=gn(muted?0:.8,C.destination);\n  NB=C.createBuffer(1,9e4,44100);NB.getChannelData(0).forEach((x,i,a)=>a[i]=Math.random()-.5);}\n  return C;}function gn(v,d){const g=new GainNode(C,{gain:v});g.connect(d||M);return g;}\nfunction bq(type,f,d){const b=new BiquadFilterNode(C,{type,frequency:f});b.connect(d);return b;}\nconst saw=(f,d)=>src(new OscillatorNode(C,{type:'sawtooth',frequency:f}),d);\nconst noise=d=>src(new AudioBufferSourceNode(C,{buffer:NB,loop:true}),d);\nfunction tone(type,f,t,u,v,f2,d){const g=gn(0,d),o=new OscillatorNode(C,{type,frequency:f});\n  o.frequency.setValueAtTime(f,t);if(f2)o.frequency.exponentialRampToValueAtTime(f2,t+u);\n  g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(0.001,t+u);o.connect(g);\n  o.start(t);o.stop(t+u+0.05);}function src(n,d){n.connect(d);n.start();return n;}\nfunction engine(on){if(!ac())return;const t=C.currentTime;if(on&&!E){const g=gn(0);\n  const f=bq('lowpass',900,g),ng=gn(0.02,f),nf=bq('bandpass',600,ng);\n  E={g,f,ng,n:noise(nf),a:saw(50,f),b:saw(50.6,f)};g.gain.setTargetAtTime(0.18,t,0.1);}\n  else if(!on&&E){const e=E;E=null;e.g.gain.setTargetAtTime(0,t,0.05);\n    [e.a,e.b,e.n].forEach(s=>s.stop(t+0.4));}}\nfunction setEngine(rpm,th){if(!E)return;const t=C.currentTime,r=Math.min(1,Math.max(0,+rpm||0));\n  const f=45+r*170,k=th||0,s=(p,v)=>p.setTargetAtTime(v,t,0.05);s(E.a.frequency,f);\n  s(E.b.frequency,f*(1.01+k*0.025));s(E.f.frequency,500+r*2500+k*800);s(E.ng.gain,0.03+k*0.2);}\nfunction sfx(name){if(!ac())return()=>{};const t=C.currentTime,g=gn(0.3);\n  if(name==='drift'){const b=bq('bandpass',2600,g),n=noise(b);b.Q.value=9;\n    return()=>{g.gain.setTargetAtTime(0,C.currentTime,0.05);n.stop(C.currentTime+0.3);};}\n  if(name==='boost'){const b=bq('lowpass',300,g);noise(b).stop(t+1.2);b.Q.value=4;\n    b.frequency.setValueAtTime(300,t);b.frequency.exponentialRampToValueAtTime(5000,t+0.5);\n    g.gain.setTargetAtTime(0,t+0.35,0.15);return()=>{};}\n  const T={bump:[['square',140,0,.15,.5,40]],beep:[['square',660,0,.15,.4]],\n    go:[['square',1320,0,.45,.4]],lap:[['triangle',880,0,.12,.5],['triangle',1320,.12,.25,.5]],\n    finish:[523,659,784,1047].map((f,i)=>['sawtooth',f,i*.14,i>2?.7:.16,.3])}[name]||[];\n  T.forEach(a=>tone(a[0],a[1],t+a[2],a[3],a[4],a[5],g));return()=>{};}\nfunction music(on){if(!ac())return;if(!on||mus){if(!on){clearInterval(mus);mus=null;}return;}\n  const lp=bq('lowpass',900,gn(0.4)),R=[[110,164.8],[87.3,130.8],[130.8,196],[98,146.8]],q=30/110;\n  let i=0,nt=C.currentTime+0.1;mus=setInterval(()=>{while(nt<C.currentTime+0.3){\n    tone('sawtooth',R[(i>>4)&3][i&1],nt,q*.9,.3,0,lp);if(!(i&1))tone('sine',110,nt,.3,.45,40,M);\n    nt+=q;i++;}},100);}\nfunction mute(on){muted=!!on;if(C)M.gain.setTargetAtTime(muted?0:.8,C.currentTime,.02);}\n```\n\n**How it works**\n\n- **When audio starts:** the AudioContext is created lazily inside `ac()`. This happens only after the first `pointerup` or `keydown` has set `armed`. Those listeners run in the capture phase, so they fire before the game's own handlers, including the Enter, click or tap on START.\n  - Before that first action, every function does nothing.\n  - `sfx()` returns a no-op stop function in that case.\n  - Later gestures resume a suspended context.\n- **No audio files:** all sounds use oscillators and one generated noise buffer.\n- **Top level:** nothing runs by itself. The only top-level actions are function and constant definitions and the two unlock listeners. The music's `setInterval` exists only after `music(true)` is called.\n- **Engine:** two sawtooths detuned by about 1–3.5% go through a low-pass filter, mixed with band-passed noise.\n  - `rpm` (0–1) sets the pitch (45–215 Hz) and opens the filter.\n  - `throttle` adds detune, filter brightness and noise for a rougher sound.\n- **Sound effects (`sfx`):**\n  - `'drift'`: a band-passed noise screech that loops until you call the returned stop function.\n  - `'boost'`: a rising low-pass noise whoosh.\n  - `'bump'`: a square-wave thud with a falling pitch.\n  - `'beep'`: a 660 Hz countdown tone.\n  - `'go'`: a 1320 Hz tone.\n  - `'lap'`: a two-note chime.\n  - `'finish'`: a four-note C-major sawtooth fanfare.\n- **Music:** 110 BPM, eighth notes of 30/110 s.\n  - One sawtooth plays through a 900 Hz low-pass filter and alternates root and fifth.\n  - Chords: Am (A2/E3), F, C, then G, two bars (16 eighths) each, in a 64-step loop.\n  - A soft sine kick (110→40 Hz) plays on every beat.\n  - Notes are scheduled 0.3 s ahead every 100 ms.\n- **Mute:** `mute(on)` ramps the master gain. It also works before the context exists, because the initial gain respects it.\n\n**Suggested hookup:**\n- On race start, call `engine(true)` and `music(true)`.\n- Each frame, call `setEngine(speed/maxSpeed, throttleInput)`.\n- When a drift starts, save `stop=sfx('drift')`, and call `stop()` when it ends.\n- Call `sfx('beep')` for 3-2-1, then `sfx('go')`, `sfx('lap')` and `sfx('finish')`.\n\n**Not verified (no browser execution available here):**\n- I have not checked by listening how the engine, effects and music sound, how loud they are relative to each other, or whether the chord timing is right.\n- I have not tested the unlock on iOS Safari or Android touch. It relies on `pointerup` counting as a user activation.\n- It uses the constructors `GainNode`, `BiquadFilterNode`, `OscillatorNode` and `AudioBufferSourceNode`, with no `webkitAudioContext` fallback. Very old Safari versions are not supported.\n- If the tab is in the background, the browser slows timers, and the music may play a quick burst of notes when the tab comes back."
